import os
from typing import Any, Dict, Optional

import requests


PERSPECTIVE_API_URL = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"


def _get_attr(obj: Any, path: str, default: Any = None) -> Any:
    cur = obj
    for part in path.split("."):
        if cur is None:
            return default
        if isinstance(cur, dict):
            cur = cur.get(part, default)
        else:
            cur = getattr(cur, part, default)
    return cur if cur is not None else default


def _to_float(value: Any) -> float:
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0


def allow_text(
    text: str,
    thresholds: Optional[Dict[str, float]] = None,
    api_key: Optional[str] = None,
    language: str = "en",
) -> bool:
    """
    Applies category thresholds using Perspective API and returns True if allowed.

    thresholds keys can include:
      TOXICITY, SEVERE_TOXICITY, INSULT, PROFANITY, THREAT, IDENTITY_ATTACK, SEXUALLY_EXPLICIT
    """
    if thresholds is None:
        thresholds = {
            "TOXICITY": 0.70,
            "SEVERE_TOXICITY": 0.60,
            "INSULT": 0.75,
            "PROFANITY": 0.80,
            "THREAT": 0.50,
            "IDENTITY_ATTACK": 0.60,
            "SEXUALLY_EXPLICIT": 0.70,
        }

    api_key = api_key or os.getenv("PERSPECTIVE_API_KEY")
    if not api_key:
        raise ValueError("Perspective API key is required via api_key or PERSPECTIVE_API_KEY.")

    requested_attrs = {category: {} for category in thresholds.keys()}
    payload = {
        "comment": {"text": text},
        "languages": [language],
        "requestedAttributes": requested_attrs,
        "doNotStore": True,
    }

    response = requests.post(
        f"{PERSPECTIVE_API_URL}?key={api_key}",
        json=payload,
        timeout=20,
    )
    response.raise_for_status()
    data = response.json()

    scores = _get_attr(data, "attributeScores", {}) or {}
    for category, threshold in thresholds.items():
        summary_score = _get_attr(scores, f"{category}.summaryScore.value", 0.0)
        if _to_float(summary_score) >= float(threshold):
            return False

    return True


def moderate_text(
    text: str,
    thresholds: Optional[Dict[str, float]] = None,
    api_key: Optional[str] = None,
    language: str = "en",
) -> Dict[str, Any]:
    """
    Returns moderation result with decision and per-category scores.
    """
    if thresholds is None:
        thresholds = {
            "TOXICITY": 0.70,
            "SEVERE_TOXICITY": 0.60,
            "INSULT": 0.75,
            "PROFANITY": 0.80,
            "THREAT": 0.50,
            "IDENTITY_ATTACK": 0.60,
            "SEXUALLY_EXPLICIT": 0.70,
        }

    api_key = api_key or os.getenv("PERSPECTIVE_API_KEY")
    if not api_key:
        raise ValueError("Perspective API key is required via api_key or PERSPECTIVE_API_KEY.")

    payload = {
        "comment": {"text": text},
        "languages": [language],
        "requestedAttributes": {category: {} for category in thresholds.keys()},
        "doNotStore": True,
    }

    response = requests.post(
        f"{PERSPECTIVE_API_URL}?key={api_key}",
        json=payload,
        timeout=20,
    )
    response.raise_for_status()
    data = response.json()

    scores = _get_attr(data, "attributeScores", {}) or {}
    category_scores: Dict[str, float] = {}
    triggered = {}

    allowed = True
    for category, threshold in thresholds.items():
        score = _to_float(_get_attr(scores, f"{category}.summaryScore.value", 0.0))
        category_scores[category] = score
        hit = score >= float(threshold)
        triggered[category] = hit
        if hit:
            allowed = False

    return {
        "allowed": allowed,
        "thresholds": dict(thresholds),
        "scores": category_scores,
        "triggered": triggered,
        "raw": data,
    }
